import json
import logging
import networkx as nx
from typing import Dict, List, Any, Optional
from pathlib import Path
from collections import defaultdict

from code.config import PROCESSED_DIR, RESULTS_DIR

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

def load_graphs() -> Dict[str, Any]:
    """Load the graphs generated by the graph builder."""
    graph_path = PROCESSED_DIR / "graphs.json"
    if not graph_path.exists():
        raise FileNotFoundError(f"Graphs file not found at {graph_path}. Run graph_builder first.")
    
    with open(graph_path, 'r') as f:
        return json.load(f)

def load_retrieval_scores() -> List[Dict[str, Any]]:
    """Load the retrieval scores generated by the retrieval simulation."""
    scores_path = RESULTS_DIR / "retrieval_scores.csv"
    if not scores_path.exists():
        raise FileNotFoundError(f"Retrieval scores file not found at {scores_path}. Run retrieval_sim first.")
    
    scores = []
    with open(scores_path, 'r') as f:
        # Simple CSV parsing without pandas to avoid extra dependencies if not installed
        lines = f.readlines()
        if not lines:
            return []
        
        headers = lines[0].strip().split(',')
        for line in lines[1:]:
            values = line.strip().split(',')
            if len(values) == len(headers):
                row = dict(zip(headers, values))
                scores.append(row)
    return scores

def calculate_topological_metrics(graph: nx.Graph) -> Dict[str, float]:
    """Calculate topological metrics for a single graph."""
    metrics = {}
    
    if len(graph.nodes()) == 0:
        # Default metrics for empty graph
        metrics['modularity'] = 0.0
        metrics['avg_path_length'] = 0.0
        metrics['avg_degree'] = 0.0
        metrics['max_degree'] = 0.0
        metrics['avg_betweenness'] = 0.0
        metrics['max_betweenness'] = 0.0
        metrics['num_nodes'] = 0
        metrics['num_edges'] = 0
        return metrics

    metrics['num_nodes'] = len(graph.nodes())
    metrics['num_edges'] = len(graph.edges())
    
    # Degree metrics
    degrees = [d for n, d in graph.degree()]
    metrics['avg_degree'] = float(sum(degrees) / len(degrees)) if degrees else 0.0
    metrics['max_degree'] = float(max(degrees)) if degrees else 0.0

    # Betweenness centrality (sampled for large graphs to save time)
    try:
        betweenness = nx.betweenness_centrality(graph, k=min(100, len(graph.nodes())))
        betweenness_values = list(betweenness.values())
        metrics['avg_betweenness'] = float(sum(betweenness_values) / len(betweenness_values)) if betweenness_values else 0.0
        metrics['max_betweenness'] = float(max(betweenness_values)) if betweenness_values else 0.0
    except Exception as e:
        logger.warning(f"Could not calculate betweenness centrality: {e}")
        metrics['avg_betweenness'] = 0.0
        metrics['max_betweenness'] = 0.0

    # Modularity (requires communities, use a simple partition if none exist)
    try:
        # Try to detect communities using Louvain method
        if len(graph.nodes()) > 1:
            try:
                import community as community_louvain
                partition = community_louvain.best_partition(graph)
                communities = list(partition.values())
                metrics['modularity'] = float(nx.community.modularity(graph, communities))
            except ImportError:
                # Fallback: use a simple random partition or 0
                logger.warning("python-louvain not installed, using modularity=0")
                metrics['modularity'] = 0.0
            except Exception as e:
                logger.warning(f"Modularity calculation failed: {e}")
                metrics['modularity'] = 0.0
        else:
            metrics['modularity'] = 0.0
    except Exception as e:
        logger.warning(f"Could not calculate modularity: {e}")
        metrics['modularity'] = 0.0

    # Average path length (only for connected graphs or largest component)
    try:
        if nx.is_connected(graph):
            metrics['avg_path_length'] = float(nx.average_shortest_path_length(graph))
        else:
            # Use largest connected component
            largest_cc = max(nx.connected_components(graph), key=len)
            subgraph = graph.subgraph(largest_cc)
            if len(subgraph.nodes()) > 1:
                metrics['avg_path_length'] = float(nx.average_shortest_path_length(subgraph))
            else:
                metrics['avg_path_length'] = 0.0
    except Exception as e:
        logger.warning(f"Could not calculate average path length: {e}")
        metrics['avg_path_length'] = 0.0

    return metrics

def extract_features_for_retrieved_docs(
    graphs: Dict[str, Any], 
    retrieval_scores: List[Dict[str, Any]], 
    k: int = 10
) -> List[Dict[str, Any]]:
    """
    Extract topological signatures ONLY from the set of documents returned by the TF-IDF ranking.
    
    Args:
        graphs: Dictionary of document_id -> graph data (from graphs.json)
        retrieval_scores: List of retrieval score records (from retrieval_scores.csv)
        k: Number of top retrieved documents to consider per query (default 10)
        
    Returns:
        List of dictionaries containing query_id, doc_id, and topological features
    """
    retrieved_features = []
    
    # Group retrieval scores by query_id
    query_docs = defaultdict(list)
    for score_record in retrieval_scores:
        query_id = score_record.get('query_id')
        doc_id = score_record.get('doc_id')
        rank = int(score_record.get('rank', float('inf')))
        
        if query_id and doc_id and rank <= k:
            query_docs[query_id].append({
                'doc_id': doc_id,
                'rank': rank,
                'score': float(score_record.get('score', 0.0))
            })
    
    # Process each query's top-k retrieved documents
    for query_id, docs in query_docs.items():
        # Sort by rank
        docs.sort(key=lambda x: x['rank'])
        
        for doc_info in docs:
            doc_id = doc_info['doc_id']
            
            # Retrieve the graph for this document
            # Note: graphs.json structure from T016 is expected to be {doc_id: graph_data}
            graph_data = graphs.get(doc_id)
            
            if graph_data is None:
                logger.warning(f"No graph found for document {doc_id}, skipping.")
                continue
            
            # Reconstruct NetworkX graph from saved data
            # Assuming graph_data has 'nodes' and 'edges' keys
            try:
                G = nx.Graph()
                G.add_nodes_from(graph_data.get('nodes', []))
                edges = graph_data.get('edges', [])
                # Edges might be tuples or lists
                G.add_edges_from(edges)
                
                # Calculate topological metrics
                metrics = calculate_topological_metrics(G)
                
                # Add query and doc info
                feature_record = {
                    'query_id': query_id,
                    'doc_id': doc_id,
                    'rank': doc_info['rank'],
                    'retrieval_score': doc_info['score'],
                    **metrics
                }
                
                retrieved_features.append(feature_record)
                
            except Exception as e:
                logger.error(f"Error processing graph for doc {doc_id}: {e}")
                continue

    return retrieved_features

def save_retrieved_features(features: List[Dict[str, Any]], output_path: Optional[Path] = None):
    """Save the retrieved features to a CSV file."""
    if output_path is None:
        output_path = RESULTS_DIR / "retrieved_features.csv"
    
    if not features:
        logger.warning("No features to save. Creating empty file with headers.")
        # Create file with headers even if empty
        with open(output_path, 'w', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=[
                'query_id', 'doc_id', 'rank', 'retrieval_score',
                'modularity', 'avg_path_length', 'avg_degree', 'max_degree',
                'avg_betweenness', 'max_betweenness', 'num_nodes', 'num_edges'
            ])
            writer.writeheader()
        return

    # Determine fieldnames from the first record
    fieldnames = list(features[0].keys())
    
    with open(output_path, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(features)
    
    logger.info(f"Saved {len(features)} retrieved feature records to {output_path}")

def run_pipeline_from_retrieval_scores(k: int = 10, output_path: Optional[Path] = None):
    """
    Main pipeline function to extract topological signatures from retrieved documents.
    
    This function:
    1. Loads graphs from data/processed/graphs.json
    2. Loads retrieval scores from data/results/retrieval_scores.csv
    3. Extracts topological metrics ONLY for the top-k retrieved documents per query
    4. Saves the results to data/results/retrieved_features.csv
    """
    logger.info("Starting topological signature extraction from retrieved documents...")
    
    # Load input data
    logger.info("Loading graphs...")
    graphs = load_graphs()
    logger.info(f"Loaded {len(graphs)} graphs.")
    
    logger.info("Loading retrieval scores...")
    retrieval_scores = load_retrieval_scores()
    logger.info(f"Loaded {len(retrieval_scores)} retrieval score records.")
    
    # Extract features
    logger.info(f"Extracting features for top-{k} retrieved documents per query...")
    features = extract_features_for_retrieved_docs(graphs, retrieval_scores, k=k)
    logger.info(f"Extracted {len(features)} feature records.")
    
    # Save output
    logger.info(f"Saving results to {output_path or RESULTS_DIR / 'retrieved_features.csv'}...")
    save_retrieved_features(features, output_path)
    
    logger.info("Pipeline completed successfully.")
    return features

def run_pipeline():
    """Entry point for the pipeline."""
    run_pipeline_from_retrieval_scores()

def main():
    """Command-line entry point."""
    import argparse
    parser = argparse.ArgumentParser(description="Extract topological signatures from retrieved documents")
    parser.add_argument('--k', type=int, default=10, help='Number of top retrieved documents to consider per query')
    parser.add_argument('--output', type=str, default=None, help='Output file path')
    args = parser.parse_args()
    
    output_path = Path(args.output) if args.output else None
    run_pipeline_from_retrieval_scores(k=args.k, output_path=output_path)

if __name__ == "__main__":
    main()
